const BF_VB = "380 280 1240 1440";
const REDUCED = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
function morphPath(t, col){
  let d = "";
  for(const r of MORPH){
    if(r.c!==col) continue;
    const a=r.a, b=r.b, n=a.length;
    for(let i=0;i<n;i+=2){
      d += (i?" ":"M") + ((1-t)*a[i]+t*b[i]).toFixed(1) + " " + ((1-t)*a[i+1]+t*b[i+1]).toFixed(1);
    }
    d += "Z";
  }
  return d;
}
const easeIO = t => t<.5 ? 4*t*t*t : 1-Math.pow(-2*t+2,3)/2;
class Butterfly {
  constructor(host, mode){
    this.host=host; this.mode=mode; this.t=-1; this.phase=Math.random()*1000;
    host.innerHTML = `<svg viewBox="${BF_VB}" aria-hidden="true"><path class="y" fill="#FFD468"/><path class="p" fill="#945777"/></svg>`;
    this.y=host.querySelector(".y"); this.p=host.querySelector(".p");
    this.set(0);
    if(mode==="hover"){ host.addEventListener("pointerenter",()=>{this.hover=true}); host.addEventListener("pointerleave",()=>{this.hover=false}); }
    BFS.push(this);
  }
  set(t){ if(Math.abs(t-this.t)<0.004) return; this.t=t; this.y.setAttribute("d",morphPath(t,"Y")); this.p.setAttribute("d",morphPath(t,"P")); }
  tick(now){
    if(REDUCED || this.mode==="still") return;
    if(this.mode==="hover" && !this.hover){ this.set(Math.max(0,this.t-0.08)); return; }
    // idle: slow flap — long hold at wings-out, quick dip to wings-down
    const period = this.mode==="hover" ? 700 : 2600;
    const u = ((now+this.phase)%period)/period;
    let f = u<0.62 ? 0 : (u-0.62)/0.38;       // last 38% of the cycle is the flap
    f = Math.sin(f*Math.PI);                    // out -> down -> out
    this.set(easeIO(f));
  }
}
const BFS=[];
document.querySelectorAll("[data-butterfly]").forEach(el => new Butterfly(el, el.dataset.butterfly||"idle"));
document.querySelectorAll("[data-wordmark]").forEach(el => { el.innerHTML = WM[el.dataset.wordmark]; });

/* ---------- Garden hero ---------- */
const FLOWERS = [
  {key:"Picture Books", label:"Children's",           sub:"picture & board books", href:"#books",    tab:"Picture Books", kind:"daisy",  c:["#FFD468","#945777"]},
  {key:"Fiction",       label:"Fiction & Literature", sub:"novels & stories",      href:"#books",    tab:"Fiction",       kind:"bell",   c:["#D8DDF0","#5E3349"]},
  {key:"Design & Art",  label:"Art & Design",         sub:"monographs & manuals",  href:"#books",    tab:"Design & Art",  kind:"sun",    c:["#945777","#FFD468"]},
  {key:"Non-fiction",   label:"Non-Fiction",          sub:"essays & ideas",        href:"#books",    tab:"Non-fiction",   kind:"spike",  c:["#BFD9D0","#2F5C4E"]},
  {key:"Lifestyle",     label:"Lifestyle",            sub:"food, home & city",     href:"#books",    tab:"Non-fiction",   kind:"tulip",  c:["#F6C7B1","#7A3A2C"]},
  {key:"gifts",         label:"Gifts & Games",        sub:"non-books",             href:"#nonbooks", tab:null,            kind:"pom",    c:["#F4E7EE","#945777"]},
  {key:"events",        label:"Events",               sub:"this month's exhibition",href:"#events",  tab:null,            kind:"star",   c:["#FFD468","#5E3349"]}
];
// layouts: [x, stem height] per flower, in viewBox units; ground at G
const LAYOUTS = {
  wide:  {vb:[0,0,1400,620], G:580, pos:[[640,250],[760,400],[880,270],[1000,440],[1120,300],[1240,410],[1350,260]]},
  narrow:{vb:[0,0,480,740],  G:700, pos:[[75,180],[270,340],[420,220],[150,470],[330,570],[60,600],[440,480]]}
};
function flowerSVG(f, x, G, h, i, W){
  const [bg,fg]=f.c, top=G-h, sway=(i%2?1:-1)*18;
  let head="";
  const R=44;
  if(f.kind==="daisy"){ head=Array.from({length:8},(_,k)=>`<ellipse cx="0" cy="-30" rx="13" ry="30" fill="${bg}" stroke="${fg}" stroke-width="4" transform="rotate(${k*45})"/>`).join("")+`<circle r="17" fill="${fg}"/>`; }
  if(f.kind==="bell"){ head=`<path d="M-34 -10 C-34 -50 34 -50 34 -10 L40 26 Q0 44 -40 26Z" fill="${bg}" stroke="${fg}" stroke-width="4"/><circle cx="-12" cy="14" r="4" fill="${fg}"/><circle cx="12" cy="14" r="4" fill="${fg}"/>`; }
  if(f.kind==="sun"){ head=Array.from({length:12},(_,k)=>`<path d="M0 -26 L10 -58 L-10 -58Z" fill="${fg}" transform="rotate(${k*30})"/>`).join("")+`<circle r="30" fill="${bg}" stroke="${fg}" stroke-width="4"/><circle r="12" fill="none" stroke="${fg}" stroke-width="4"/>`; }
  if(f.kind==="spike"){ head=Array.from({length:5},(_,k)=>`<circle cx="${k%2?16:-16}" cy="${-k*24}" r="15" fill="${bg}" stroke="${fg}" stroke-width="4"/>`).join("")+`<circle cx="0" cy="-118" r="12" fill="${fg}"/>`; }
  if(f.kind==="tulip"){ head=`<path d="M-30 20 C-40 -30 -14 -50 0 -20 C14 -50 40 -30 30 20 Q0 34 -30 20Z" fill="${bg}" stroke="${fg}" stroke-width="4"/><path d="M0 -20 V16" stroke="${fg}" stroke-width="4"/>`; }
  if(f.kind==="pom"){ head=Array.from({length:10},(_,k)=>`<circle cx="${Math.cos(k/10*6.283)*26}" cy="${Math.sin(k/10*6.283)*26}" r="15" fill="${bg}" stroke="${fg}" stroke-width="4"/>`).join("")+`<circle r="16" fill="${fg}"/>`; }
  if(f.kind==="star"){ head=`<path d="${Array.from({length:10},(_,k)=>{const r=k%2?22:50,a=k/10*6.283-1.5708;return (k?"L":"M")+(Math.cos(a)*r).toFixed(1)+" "+(Math.sin(a)*r).toFixed(1)}).join("")}Z" fill="${bg}" stroke="${fg}" stroke-width="4" stroke-linejoin="round"/><circle r="10" fill="${fg}"/>`; }
  const w = Math.max(f.label.length*8.2, f.sub.length*6.4)+28;
  const px = Math.max(w/2+8, Math.min(W-w/2-8, x)); // keep the label on-canvas
  const stem=`<path d="M${x} ${G} C${x} ${G-h*.4} ${x+sway} ${G-h*.6} ${x} ${top+R-10}" fill="none" stroke="${fg}" stroke-width="5" stroke-linecap="round"/>
    <path d="M${x} ${G-h*.35} c-30 -28 -60 -18 -62 6 c26 14 52 4 62 -6Z" fill="${bg}" stroke="${fg}" stroke-width="4" stroke-linejoin="round"/>
    <path d="M${x} ${G-h*.55} c30 -28 60 -18 62 6 c-26 14 -52 4 -62 -6Z" fill="${bg}" stroke="${fg}" stroke-width="4" stroke-linejoin="round"/>`;
  const py = top+R+18;
  return `<a class="flower" href="${f.href}" data-flower="${i}" ${f.tab?`data-tab="${f.tab}"`:""} aria-label="${f.label} — ${f.sub}">
    ${stem}<g class="head" transform="translate(${x} ${top})">${head}</g>
    <g transform="translate(${px} ${py})"><rect class="pill" x="${-w/2}" y="0" width="${w}" height="44" rx="22" stroke-width="1.5"/><text class="lbl" x="0" y="19" text-anchor="middle">${f.label}</text><text class="lbl-sub" x="0" y="35" text-anchor="middle">${f.sub}</text></g>
  </a>`;
}
const garden=document.getElementById("garden");
let gardenState=null;
function buildGarden(){
  const L = window.innerWidth<=900 ? LAYOUTS.narrow : LAYOUTS.wide;
  if(gardenState && gardenState.L===L) return;
  const [,,W,H]=L.vb, G=L.G;
  const flowers=FLOWERS.map((f,i)=>flowerSVG(f,L.pos[i][0],G,L.pos[i][1],i,W)).join("");
  const grass=Array.from({length:Math.round(W/40)},(_,k)=>{const gx=k*40+15;return `<path d="M${gx} ${G} q6 -22 14 -34 M${gx+8} ${G} q0 -18 -6 -30" fill="none" stroke="#945777" stroke-width="3" stroke-linecap="round" opacity=".55"/>`}).join("");
  garden.innerHTML = `<svg viewBox="${L.vb.join(" ")}" role="group">
    <circle cx="${W>1000?W*.72:W*.5}" cy="${H*.18}" r="${Math.min(W,H)*.2}" fill="#FFF0C4"/>
    <circle cx="${W>1000?W*.72:W*.5}" cy="${H*.18}" r="${Math.min(W,H)*.27}" fill="none" stroke="#945777" stroke-width="1.5" stroke-dasharray="2 9" opacity=".5"/>
    ${grass}
    <path d="M0 ${G} H${W}" stroke="#945777" stroke-width="3" stroke-linecap="round"/>
    ${flowers}
    <g id="gbf"><g id="gbfInner"><path class="y" fill="#FFD468"/><path class="p" fill="#945777"/></g></g>
  </svg>`;
  const gbf=garden.querySelector("#gbf"), inner=garden.querySelector("#gbfInner");
  const y=gbf.querySelector(".y"), p=gbf.querySelector(".p");
  const S = W>1000 ? 0.115 : 0.1;
  // landing spots: top of each flower head, butterfly anchored at its spine base (990,1300)
  const spots = FLOWERS.map((f,i)=>{ const [x,h]=L.pos[i]; const top=G-h; const lift = {daisy:62,bell:52,sun:60,spike:134,tulip:52,pom:44,star:52}[f.kind]; return {x, y: top-lift+4}; });
  gardenState = {L, gbf, inner, y, p, S, spots, i:0, state:"land", until:performance.now()+2200, from:null, to:null, t0:0, dur:0, tm:-1, next:null, W, H};
  placeAt(spots[0].x, spots[0].y, 0, 0);
  garden.querySelectorAll(".flower").forEach(el=>{
    el.addEventListener("pointerenter",()=>{ gardenState.next=+el.dataset.flower; if(gardenState.state==="land" && gardenState.i!==gardenState.next) gardenState.until=Math.min(gardenState.until, performance.now()+250); });
  });
  markHere(0);
}
function placeAt(x,y,rot,tm){
  const s=gardenState; s.gbf.setAttribute("transform",`translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${rot.toFixed(1)}) scale(${s.S}) translate(-990 -1640)`);
  if(Math.abs(tm-s.tm)>0.004){ s.tm=tm; s.y.setAttribute("d",morphPath(tm,"Y")); s.p.setAttribute("d",morphPath(tm,"P")); }
}
function markHere(i){ garden.querySelectorAll(".flower").forEach((el,k)=>el.classList.toggle("here",k===i)); }
function gardenTick(now){
  const s=gardenState; if(!s) return;
  if(s.state==="land"){
    const sp=s.spots[s.i];
    // resting: mostly wings out, an occasional slow flap; slight breathing bob
    const u=((now)%3200)/3200; let f=u<0.7?0:(u-0.7)/0.3; f=Math.sin(f*Math.PI);
    placeAt(sp.x, sp.y+Math.sin(now/600)*1.5, Math.sin(now/900)*2, REDUCED?0:easeIO(f)*0.85);
    if(now>=s.until && !REDUCED){
      let j = s.next!=null && s.next!==s.i ? s.next : (s.i+1+Math.floor(Math.random()*(FLOWERS.length-1)))%FLOWERS.length;
      s.next=null; s.from=s.spots[s.i]; s.to=s.spots[j]; s.i=j; s.state="fly"; s.t0=now;
      const dist=Math.hypot(s.to.x-s.from.x,s.to.y-s.from.y); s.dur=1400+dist*1.6;
      markHere(-1);
    }
  } else {
    const u=Math.min(1,(now-s.t0)/s.dur), e=easeIO(u);
    const {from,to}=s; const mx=(from.x+to.x)/2, arc=Math.min(200, 90+Math.abs(to.x-from.x)*0.25);
    // quadratic arc: up and over
    const cx=mx, cy=Math.min(from.y,to.y)-arc;
    const x=(1-e)*(1-e)*from.x+2*(1-e)*e*cx+e*e*to.x, y=(1-e)*(1-e)*from.y+2*(1-e)*e*cy+e*e*to.y;
    const dx=(to.x-from.x); const rot=Math.sin(u*Math.PI)*Math.sign(dx)*10;
    const flap=(Math.sin(now/95)+1)/2;                          // fast flap in flight
    const settle = u>0.85 ? (1-(u-0.85)/0.15) : 1;              // glide in with wings opening
    placeAt(x,y,rot,flap*settle);
    if(u>=1){ s.state="land"; s.until=now+2600+Math.random()*1400; markHere(s.i); }
  }
}
buildGarden();
let rebuildT; window.addEventListener("resize",()=>{ clearTimeout(rebuildT); rebuildT=setTimeout(buildGarden,150); });

/* ---------- Animation loop ---------- */
function loop(now){
  for(const b of BFS){ if(b.host.offsetParent!==null || b.host.closest(".toast")) b.tick(now); }
  if(garden.offsetParent!==null) gardenTick(now);
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

